constexpr uint8_t kScriptUponTimeout = 1; // UPON_TIMEOUT: run only when the movie is cut short
constexpr uint8_t kScriptReversed = 2;    // chat flag CFReversed
constexpr int kScriptMaxArgs = 10;

struct ScriptCmd {
    ScriptOp op;
    uint8_t flags;       // kScriptUponTimeout | kScriptReversed
    ScriptVar var;       // first variable operand
    ScriptVar var2;      // second (REPARENTTO parent, CC_CHAT_TO_CONFIRM target)
    int8_t quit;         // chat: quitButton (1 = the last page closes the dialog)
    uint8_t numArgs;     // numbers in args[]
    const char* key;     // chat: the TTLocalizer name
    const char* text;    // chat text (boy toon for CC_*), or the command's string operand
    const char* textAlt; // CC_* chat text for a girl toon (Minnie); nullptr otherwise
    const char* str2;    // second string operand (LOAD sub-node, REPARENTTO node path)
    float args[kScriptMaxArgs];
};

struct ScriptDef {
    const char* name; // QuestScripts.txt ID
    const ScriptCmd* cmds;
    int numCmds;
};

